examples.sql:
SELECT payload, json_schema_is_valid(
  '{"type":"integer"}', payload
) AS valid
FROM (VALUES ('5'::JSON), ('"five"'::JSON))
  t(payload);
-- 5: true; "five": false

SELECT unnest(json_schema_errors(
  '{"properties":{"age":{"minimum":0}}}',
  '{"age":-1}'
), recursive := true);
-- /age | minimum | Minimum value is 0 …

SET VARIABLE schema = '{
  "type":"object",
  "properties":{
    "retries":{"type":"integer","default":3}
  }
}';
SELECT json_schema_validate_schema(
  getvariable('schema'));
SELECT json_schema_update(
  getvariable('schema'), '{}');
-- {"retries":3}
SELECT json_schema_patch(
  getvariable('schema'), '{}');
